//! The two generated files: the scheme JSON (one class per line, so a
//! rebuild diffs line by line) and SOURCES.md.

use std::fmt::Write;

use shelfmark_core::scheme::SchemeDoc;

use crate::build::Stats;
use crate::sources::{Lock, Role};

/// The scheme as JSON: header fields pretty-printed, then one class per
/// line.
pub fn scheme_json(doc: &SchemeDoc) -> Result<String, String> {
    let err = |e: serde_json::Error| e.to_string();
    let mut head = doc.clone();
    head.classes.clear();
    let head = serde_json::to_string_pretty(&head).map_err(err)?;
    let head = head
        .trim_end()
        .strip_suffix('}')
        .and_then(|h| h.trim_end().strip_suffix("\"classes\": []"))
        .ok_or("unexpected scheme JSON layout")?;
    let mut out = format!("{head}\"classes\": [\n");
    for (i, c) in doc.classes.iter().enumerate() {
        let sep = if i + 1 < doc.classes.len() { "," } else { "" };
        let _ = writeln!(out, "    {}{sep}", serde_json::to_string(c).map_err(err)?);
    }
    out.push_str("  ]\n}\n");
    Ok(out)
}

/// SOURCES.md: the license, each source's lock entry and what the build
/// kept and dropped.
pub fn sources_md(lock: &Lock, s: &Stats, doc: &SchemeDoc) -> String {
    let mut o = String::new();
    let _ = write!(
        o,
        "# IPC scheme: sources\n\n\
         Generated by `schemes/ipc/builder` (`ipc-scheme build`); do not edit by hand.\n\
         `ipc.json` is scheme `{name}@{version}` with {n} classes and validates against\n\
         `schemas/scheme.schema.json` and `shelfmark_core::scheme::SchemeDoc`.\n\n\
         ## Rebuild\n\n\
         ```sh\n\
         cd schemes/ipc/builder\n\
         cargo run --release -- fetch --cache /tmp/ipc-sources   # network; rewrites sources.lock.json\n\
         cargo run --release -- build --cache /tmp/ipc-sources   # offline; deterministic from the lock\n\
         cargo run --release -- check --cache /tmp/ipc-sources   # fails if ipc.json or SOURCES.md is stale\n\
         ```\n\n\
         `build` refuses any cached archive, or XML member inside it, whose sha256 differs from\n\
         `sources.lock.json`. `fetch --edition YYYYMMDD` pins another edition.\n\n\
         ## License\n\n\
         The IPC master files are published by the World Intellectual Property Organization (WIPO)\n\
         and are freely available for download. Under WIPO's Open Access Policy\n\
         (<https://www.wipo.int/tools/en/disclaim.html>, checked 2026-10-08), WIPO online content is\n\
         licensed CC BY 4.0 unless marked otherwise; the master files carry no other notice. CC BY 4.0\n\
         allows redistribution, including inside an open-source binary, on condition of attribution\n\
         and a statement of changes. Attribution: \"International Patent Classification (IPC),\n\
         World Intellectual Property Organization (WIPO), edition {edition}. Licensed CC BY 4.0.\n\
         Reformatted by shelfmark; not endorsed by WIPO.\" Changes: symbols are written without\n\
         their space, title parts are joined by `; `, images are written `[image]`, notes are\n\
         dropped and references move to each class's `note`. WIPO's name and emblem do not imply\n\
         endorsement.\n\n\
         ## Sources\n\n\
         | file | role | fetched | bytes | sha256 | XML member | member sha256 |\n\
         |---|---|---|---|---|---|---|\n",
        name = doc.name,
        version = doc.version,
        n = doc.classes.len(),
        edition = lock.edition,
    );
    for l in &lock.sources {
        let role = match l.role {
            Role::Scheme => "scheme",
            Role::Catchwords => "catchword index",
        };
        let _ = writeln!(
            o,
            "| [{}]({}) | {role} | {} | {} | `{}` | {} | `{}` |",
            l.file, l.url, l.fetched, l.bytes, l.sha256, l.member, l.member_sha256
        );
    }
    let _ = write!(
        o,
        "\n## What the build kept\n\n\
         | | count |\n|---|---|\n\
         | sections | {} |\n| classes | {} |\n| subclasses | {} |\n| main groups | {} |\n\
         | subgroups | {} |\n| of which indexing-scheme entries | {} |\n\
         | catchword entries with a reference | {} |\n| catchword links (`ipc-catchword`) | {} |\n\
         | guidance headings | {} |\n| heading links (`ipc-heading`) | {} |\n\n\
         Dropped: {} non-class entries (notes, subclass indexes, the sections' class-title lists).\n\
         {} title images are written `[image]`.\n",
        s.sections,
        s.classes,
        s.subclasses,
        s.main_groups,
        s.subgroups,
        s.indexing,
        s.catchwords,
        s.catchword_links,
        s.headings,
        s.heading_links,
        s.skipped,
        s.images,
    );
    if s.unresolved.is_empty() {
        o.push_str("Every catchword reference resolves to a class.\n");
    } else {
        let _ = writeln!(
            o,
            "{} catchword references name no class in this edition and are skipped: {}.",
            s.unresolved.len(),
            s.unresolved.join(", ")
        );
    }
    o.push_str(
        "\n## Links to LCC and LCSH\n\n\
         None. The IPC master files (scheme, catchword index, concordance, definitions) link only\n\
         to IPC symbols and earlier IPC editions; WIPO publishes no IPC-to-LCC or IPC-to-LCSH\n\
         mapping, so the scheme carries no `lcc` or `lcsh` vocabulary.\n",
    );
    o
}
